225:export const FREEMC_PLUGIN_MC_VERSION = "26.1.2";
---items---
/**
 * Curated catalog of `minecraft:`-namespaced item ids for the free-tier
 * inventory editor (components/customer/freemc/InventoryEditor.tsx).
 *
 * This is NOT the full ~1400-item vanilla registry — it's a few hundred
 * entries covering what a player would actually want to grant someone:
 * tools/weapons/armor across every material tier, common building blocks,
 * ores/valuables, food, potions/brewing ingredients, redstone, farming, and
 * assorted utility items. Every `id` here is a real item id valid for
 * `/item replace entity <player> <slot> with <id>` on a current (26.x)
 * vanilla/Paper server — plain module, no "use server" (imported by both the
 * server action and the client component).
 */

export type MinecraftItem = { id: string; label: string; category: string };

function title(s: string): string {
  return s
    .split("_")
    .map((w) => w.charAt(0).toUpperCase() + w.slice(1))
    .join(" ");
}

function item(id: string, category: string, label?: string): MinecraftItem {
  return { id: `minecraft:${id}`, label: label ?? title(id), category };
}

// ---- Tools & weapons: generated across every real material tier -----------
// Tools only ever come in wood/stone/iron/golden/diamond/netherite — there is
// no leather/chainmail tool. Swords are grouped with tools here (categorized
// as "Weapons" separately below along with bow/crossbow/trident/etc).
const TOOL_MATERIALS = ["wooden", "stone", "iron", "golden", "diamond", "netherite"];
const TOOL_KINDS = ["pickaxe", "axe", "shovel", "hoe"];
const SWORD_MATERIALS = TOOL_MATERIALS;

const tools: MinecraftItem[] = TOOL_MATERIALS.flatMap((mat) =>
  TOOL_KINDS.map((kind) => item(`${mat}_${kind}`, "Tools")),
);

const weapons: MinecraftItem[] = [
  ...SWORD_MATERIALS.map((mat) => item(`${mat}_sword`, "Weapons")),
  item("bow", "Weapons"),
  item("crossbow", "Weapons"),
  item("trident", "Weapons"),
  item("shield", "Weapons"),
  item("arrow", "Weapons"),
  item("spectral_arrow", "Weapons"),
  item("mace", "Weapons"),
];

