const results: InventoryEditResult[] = [];
for (const edit of parsed.edits) {
  const clearing = edit.itemId === "minecraft:air";
  // MUST be namespaced "minecraft:item", not bare "item" — see the
  // root-cause note above PLAYER_NAME_RE. Plugin-kind presets that
  // bundle EssentialsX (SkyBlock, Towny) register their OWN "item"
  // command ("Spawn an item [to yourself]", usage `/item <item> [amount]`)
  // and Bukkit's command map gives a plugin's registration priority over
  // the vanilla one for the same unqualified label. Sent bare, this
  // command was being swallowed by Essentials' handler — which parsed
  // "replace" as a (nonexistent) item id and, since the RCON/console
  // sender isn't a player, had nothing to spawn it into anyway — so it
  // silently no-opped instead of ever reaching the real
  // `/item replace entity ... with ...` vanilla command. The
  // "minecraft:" namespace prefix forces command dispatch to the
  // vanilla implementation regardless of what any plugin has
  // registered under the bare label. Live-verified: on both a
  // vanilla-command-only server (Prison preset, no EssentialsX) and via
  // the plugin.yml of the EssentialsX jar actually shipped on the
  // SkyBlock/Towny presets, `minecraft:item replace entity ...`
  // resolves to the identical vanilla handler (confirmed by getting the
  // same "Invalid name or UUID" vanilla error text as the unprefixed
  // form against a server with no competing "item" command).
  const command = clearing
    ? `minecraft:item replace entity ${match.name} ${edit.slot} with minecraft:air`
    : `minecraft:item replace entity ${match.name} ${edit.slot} with ${edit.itemId} ${edit.count}`;
  const r = await sendRcon(conn, row.containerName, user.id, command);
